"""Check exact flagship delivery identities, CSP and reproducible generation."""

from __future__ import annotations

import base64
import hashlib
import json
import re
import subprocess
import sys
import tempfile
import unittest
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


class DeliveryTests(unittest.TestCase):
    """Generated bytes must match the source a reviewer can inspect."""

    def test_regeneration_is_exact(self) -> None:
        """A clean source regeneration cannot silently drift from delivered bytes."""
        paths = [ROOT / "docs/successor/alpha" / name for name in ("index.html", "sources.json")]
        before = [path.read_bytes() for path in paths]
        subprocess.run([sys.executable, "scripts/generate_successor_alpha.py"], cwd=ROOT, check=True)
        self.assertEqual(before, [path.read_bytes() for path in paths])

    def test_manifest_and_artwork_bind_exact_bytes(self) -> None:
        """Every delivered implementation and supplied artwork source has an exact digest."""
        manifest = json.loads((ROOT / "docs/successor/alpha/sources.json").read_text())
        for path, expected in manifest["sources"].items():
            self.assertEqual(hashlib.sha256((ROOT / path).read_bytes()).hexdigest(), expected, path)
        page = ROOT / "docs/successor/alpha/index.html"
        self.assertEqual(hashlib.sha256(page.read_bytes()).hexdigest(), manifest["pageSha256"])
        artwork = json.loads((ROOT / "examples/successor-alpha/artwork.json").read_text())
        self.assertEqual(hashlib.sha256((ROOT / artwork["asset"]).read_bytes()).hexdigest(), artwork["sha256"])

    def test_complete_gallery_keeps_portable_page_identity(self) -> None:
        with tempfile.TemporaryDirectory() as folder:
            page = Path(folder) / "successor/alpha/index.html"
            page.parent.mkdir(parents=True)
            before = (ROOT / "docs/successor/alpha/index.html").read_bytes()
            page.write_bytes(before)
            subprocess.run(
                [
                    sys.executable,
                    "-c",
                    "from pathlib import Path; import sys; "
                    "from scripts.generate_gallery_html import insert_back_link; "
                    "insert_back_link([Path(sys.argv[1])])",
                    str(page),
                ],
                cwd=ROOT,
                check=True,
            )
            self.assertEqual(page.read_bytes(), before)

    def test_bundled_compiler_permission_notice_is_retained(self) -> None:
        page = (ROOT / "docs/successor/alpha/index.html").read_text(encoding="utf-8")
        self.assertIn("MIT License", page)
        self.assertIn("Copyright (c) 2025 MONTREAL.AI", page)
        self.assertIn("Permission is hereby granted", page)

    def test_csp_hashes_match_only_executable_script_and_style(self) -> None:
        """The portable page executes shipped code while input files stay inert."""
        page = (ROOT / "docs/successor/alpha/index.html").read_text()
        self.assertNotIn("{{", page)
        self.assertIn("default-src 'none'", page)
        self.assertIn("worker-src blob:", page)
        self.assertIn("connect-src 'none'", page)
        scripts = re.findall(r"<script>([\s\S]*?)</script>", page)
        scriptless = re.sub(r"<script\b[^>]*>[\s\S]*?</script>", "", page)
        styles = re.findall(r"<style>([\s\S]*?)</style>", scriptless)
        self.assertEqual(len(scripts), 1)
        self.assertEqual(len(styles), 1)
        for content in [*scripts, *styles]:
            expected = "sha256-" + base64.b64encode(hashlib.sha256(content.encode()).digest()).decode()
            self.assertIn(expected, page)
        self.assertNotRegex(page, r"<script[^>]+src=")


if __name__ == "__main__":
    unittest.main()
